"""Intent tests for risk.log_returns (M1-T16, RISK-01, TC-04)."""

from __future__ import annotations

import pytest

from mdata import Prices
from risk import Returns, log_returns


def _prices(data: dict) -> Prices:
    return Prices(
        dates=tuple(data["dates"]),
        tickers=tuple(data["tickers"]),
        closes={t: tuple(v) for t, v in data["closes"].items()},
    )


@pytest.mark.intent
def test_tc04_geometric_closes_give_the_closed_form_log_returns(golden):
    given, expected = golden("risk", "TC-04")
    returns = log_returns(_prices(given["prices"]))
    assert isinstance(returns, Returns)
    assert set(returns.values) == set(expected["values"])
    for ticker, want in expected["values"].items():
        assert returns.values[ticker] == pytest.approx(want, abs=expected["tol"], rel=0)


@pytest.mark.intent
def test_tc04_returns_are_dated_by_the_later_close(golden):
    given, expected = golden("risk", "TC-04")
    returns = log_returns(_prices(given["prices"]))
    assert returns.base_date == expected["base_date"]
    assert returns.dates == tuple(expected["dates"])
    assert returns.tickers == tuple(expected["tickers"])
    for ticker in returns.tickers:
        assert len(returns.values[ticker]) == len(returns.dates)


@pytest.mark.intent
def test_contract_sample_returns_follow_the_prices_dates(contract_sample):
    data = contract_sample("mdata.Prices")
    returns = log_returns(_prices(data))
    assert returns.base_date == data["dates"][0]
    assert returns.dates == tuple(data["dates"][1:])
    assert returns.tickers == tuple(data["tickers"])


@pytest.mark.intent
def test_fewer_than_two_dates_raises_value_error(contract_sample):
    data = contract_sample("mdata.Prices")
    one_day = Prices(
        dates=tuple(data["dates"][:1]),
        tickers=tuple(data["tickers"]),
        closes={t: tuple(v[:1]) for t, v in data["closes"].items()},
    )
    with pytest.raises(ValueError, match=r"\S"):
        log_returns(one_day)

